chrome.runtime.onMessage.addListener(e=>{e.type==="JOB_DETECTED"&&(chrome.action.setBadgeText({text:"●"}),chrome.action.setBadgeBackgroundColor({color:"#22c55e"})),e.type==="JOB_APPLIED"&&(chrome.action.setBadgeText({text:"✓"}),chrome.action.setBadgeBackgroundColor({color:"#22c55e"}))});chrome.tabs.onActivated.addListener(()=>{chrome.action.setBadgeText({text:""})});chrome.tabs.onUpdated.addListener((e,t)=>{t.status==="loading"&&chrome.action.setBadgeText({text:""})});
